/* =================================
   Workspace Shell
   ================================= */

.workspace-shell {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
  background: var(--bg-deep);
}

.workspace-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.45rem 1.25rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  flex-shrink: 0;
}

.workspace-brand {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text);
  letter-spacing: -0.03em;
  margin-right: auto;
}

.workspace-brand-accent {
  background: linear-gradient(135deg, var(--accent), var(--accent-blue));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.workspace-user {
  font-family: var(--mono);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.workspace-layout {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  position: relative;
}

/* === Room Rail === */

.room-rail {
  width: 280px;
  flex-shrink: 0;
  border-right: 1px solid var(--border);
  background: var(--bg-surface);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: transform var(--duration-normal) var(--ease-out);
  z-index: 25;
}

.room-rail-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 20;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  opacity: 0;
  transition: opacity var(--duration-fast) ease;
  pointer-events: none;
}

.room-rail-backdrop.visible {
  opacity: 1;
  pointer-events: auto;
}

.room-rail-header {
  display: flex;
  align-items: center;
  padding: 0.75rem 1rem 0.5rem;
  flex-shrink: 0;
}

.room-rail-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: -0.02em;
  color: var(--text);
}

/* === Room Rail Toggle === */
.room-rail-toggle {
  display: none;
  margin-right: 0.25rem;
  font-size: 0.75rem;
  padding: 0.4rem 0.75rem;
}

/* === Chat Column === */
.chat-column {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

