/* ==============================
   pi Hub — Marvis light theme overlay
   ------------------------------
   Loaded after style.css. Active when <body> has class `theme-marvis`.
   Re-points the existing CSS variables to a Marvis-inspired light palette
   and skins a few widgets (cards, capsule buttons, chat bubbles, modal
   animation) to match the reference screenshots without rewriting the
   underlying DOM produced by main.ts.
   ============================== */

body.theme-marvis {
	/* Surface */
	--bg-deep: #f4f4f5;
	--bg-primary: #fafafa;
	--bg-surface: #ffffff;
	--bg-raised: #ffffff;
	--bg-subtle: #f4f4f5;

	/* Borders */
	--border: rgba(15, 15, 16, 0.06);
	--border-strong: rgba(15, 15, 16, 0.12);

	/* Text */
	--text: #0f0f10;
	--text-body: #1f1f23;
	--text-muted: #6b6b73;

	/* Accent — Marvis scarf red-orange, single accent (no gradient) */
	--accent: #e94b2b;
	--accent-blue: #e94b2b;
	--accent-pink: #e94b2b;
	--accent-glow: rgba(233, 75, 43, 0.14);
	--accent-soft: rgba(233, 75, 43, 0.08);
	--accent-ring: rgba(233, 75, 43, 0.28);

	/* Semantic */
	--user-bg: #efefef;
	--user-border: rgba(15, 15, 16, 0.05);
	--assistant-bg: #ffffff;
	--tool-bg: #f4f4f5;
	--error: #c8331a;
	--error-bg: rgba(200, 51, 26, 0.08);
	--error-border: rgba(200, 51, 26, 0.22);
	--warning-bg: rgba(217, 138, 4, 0.08);
	--warning-text: #b06a00;
	--plan-bg: #f4f4f5;
	--progress: #6b6b73;
	--success: #1f8a4c;
	--success-bg: rgba(31, 138, 76, 0.08);
	--success-glow: rgba(31, 138, 76, 0.18);

	/* Radii — softer, capsules */
	--radius-sm: 8px;
	--radius-md: 12px;
	--radius-lg: 16px;
	--radius-xl: 20px;
	--radius-pill: 9999px;

	/* Shadows — soft */
	--shadow-sm: 0 1px 2px rgba(15, 15, 16, 0.04);
	--shadow-md: 0 6px 20px rgba(15, 15, 16, 0.06);
	--shadow-lg: 0 16px 40px rgba(15, 15, 16, 0.10);
	--shadow-glow: 0 0 0 4px var(--accent-soft);

	color-scheme: light;
	background: var(--bg-primary);
	color: var(--text-body);
}

/* Light scrollbar */
body.theme-marvis ::-webkit-scrollbar-thumb {
	background: rgba(15, 15, 16, 0.18);
}
body.theme-marvis ::-webkit-scrollbar-thumb:hover {
	background: rgba(15, 15, 16, 0.32);
}

/* Brand: drop the dark gradient, use solid near-black */
body.theme-marvis .workspace-brand,
body.theme-marvis .workspace-brand-accent {
	background: none;
	-webkit-text-fill-color: currentColor;
	color: var(--text);
	font-weight: 600;
	letter-spacing: -0.02em;
}

/* Top accent bar — use the single accent color, thinner */
body.theme-marvis .accent-bar {
	background: var(--accent);
	height: 2px;
	opacity: 0.9;
}

/* Header: white surface, subtle hairline */
body.theme-marvis .workspace-header {
	background: var(--bg-surface);
	border-bottom: 1px solid var(--border);
}

/* Room rail: white surface */
body.theme-marvis .room-rail {
	background: var(--bg-surface);
	border-right: 1px solid var(--border);
}

/* Workspace shell base color (light) */
body.theme-marvis .workspace-shell {
	background: var(--bg-primary);
}

/* Capsule buttons — secondary */
body.theme-marvis .secondary-btn {
	border-radius: var(--radius-pill);
	background: var(--bg-subtle);
	border: 1px solid var(--border);
	color: var(--text);
	transition:
		background var(--duration-fast) var(--ease-out),
		transform var(--duration-fast) var(--ease-out),
		box-shadow var(--duration-fast) var(--ease-out);
}
body.theme-marvis .secondary-btn:hover {
	background: #ececee;
}
body.theme-marvis .secondary-btn:active {
	transform: translateY(1px);
}

/* Primary buttons in light theme — solid Marvis accent */
body.theme-marvis button.primary,
body.theme-marvis .primary-btn,
body.theme-marvis button[type="submit"]:not(.secondary-btn):not(.role-lib-tab) {
	border-radius: var(--radius-pill);
	background: var(--text);
	color: var(--bg-surface);
	border: none;
	box-shadow: var(--shadow-sm);
	transition:
		background var(--duration-fast) var(--ease-out),
		transform var(--duration-fast) var(--ease-out);
}
body.theme-marvis button.primary:hover,
body.theme-marvis .primary-btn:hover {
	background: #1f1f23;
}

/* Inputs — capsule-style for short fields, rounded-rect for textareas */
body.theme-marvis input[type="text"],
body.theme-marvis input:not([type]),
body.theme-marvis input[type="search"],
body.theme-marvis input[type="email"] {
	border-radius: var(--radius-pill);
	border: 1px solid var(--border);
	background: var(--bg-subtle);
	color: var(--text);
}
body.theme-marvis input:focus {
	outline: none;
	border-color: var(--accent-ring);
	box-shadow: 0 0 0 3px var(--accent-soft);
}

body.theme-marvis textarea,
body.theme-marvis select {
	border-radius: var(--radius-md);
	border: 1px solid var(--border);
	background: var(--bg-surface);
	color: var(--text);
}

/* Chat bubble polish: user right pill, assistant soft card */
body.theme-marvis .message.user .bubble,
body.theme-marvis .message-user .bubble,
body.theme-marvis .msg-user .bubble {
	background: var(--user-bg);
	border: 1px solid var(--user-border);
	border-radius: 18px 18px 4px 18px;
	color: var(--text);
}
body.theme-marvis .message.assistant .bubble,
body.theme-marvis .message-assistant .bubble,
body.theme-marvis .msg-assistant .bubble {
	background: var(--assistant-bg);
	border: 1px solid var(--border);
	border-radius: 4px 18px 18px 18px;
	box-shadow: var(--shadow-sm);
	color: var(--text-body);
}

/* Modal — softer, animated */
body.theme-marvis .modal-backdrop {
	background: rgba(15, 15, 16, 0.32);
	backdrop-filter: blur(6px);
	-webkit-backdrop-filter: blur(6px);
}
body.theme-marvis .modal {
	background: var(--bg-surface);
	border: 1px solid var(--border);
	border-radius: var(--radius-lg);
	box-shadow: var(--shadow-lg);
	color: var(--text);
}
@media (prefers-reduced-motion: no-preference) {
	body.theme-marvis .modal {
		animation: marvis-modal-in 220ms var(--ease-out);
	}
	body.theme-marvis .modal-backdrop {
		animation: marvis-fade-in 180ms var(--ease-out);
	}
}
@keyframes marvis-modal-in {
	from {
		opacity: 0;
		transform: translateY(8px) scale(0.97);
	}
	to {
		opacity: 1;
		transform: translateY(0) scale(1);
	}
}
@keyframes marvis-fade-in {
	from {
		opacity: 0;
	}
	to {
		opacity: 1;
	}
}

/* Loading screen overlay — light variant */
body.theme-marvis .loading-screen {
	background: var(--bg-primary);
}
body.theme-marvis .loading-screen::before {
	background: radial-gradient(ellipse 60% 50% at 50% 40%, var(--accent-soft), transparent 60%);
}
body.theme-marvis .loading-text {
	color: var(--text-muted);
}
body.theme-marvis .loading-bar-fill {
	background: var(--accent);
}

/* ============================== */
/* Office (Marvis 办公室) modal     */
/* ============================== */

.office-modal {
	width: min(960px, calc(100vw - 2rem));
	max-height: calc(100vh - 4rem);
	display: flex;
	flex-direction: column;
	gap: 1rem;
	padding: 1.25rem 1.5rem;
}
.office-header {
	display: flex;
	align-items: baseline;
	gap: 0.75rem;
}
.office-title {
	margin: 0;
	font-size: 1.1rem;
	font-weight: 600;
	letter-spacing: -0.02em;
}
.office-room {
	font-family: var(--mono);
	font-size: 0.75rem;
	color: var(--text-muted);
}
.office-body {
	display: grid;
	grid-template-columns: 1fr 240px;
	gap: 1rem;
	min-height: 0;
	flex: 1;
}
.office-stage {
	background: var(--bg-subtle);
	border-radius: var(--radius-lg);
	padding: 1rem;
	overflow: auto;
	display: flex;
	align-items: center;
	justify-content: center;
}
.office-stage svg {
	max-width: 100%;
	height: auto;
	display: block;
}
.office-side {
	display: flex;
	flex-direction: column;
	gap: 0.75rem;
}
.office-stat {
	background: var(--bg-subtle);
	border-radius: var(--radius-md);
	padding: 0.75rem 0.9rem;
	border: 1px solid var(--border);
}
.office-stat-label {
	font-size: 0.7rem;
	color: var(--text-muted);
	text-transform: uppercase;
	letter-spacing: 0.06em;
	margin: 0 0 0.25rem;
}
.office-stat-value {
	font-size: 1.25rem;
	font-weight: 600;
	color: var(--text);
	margin: 0;
}
.office-stat-row {
	display: grid;
	grid-template-columns: 1fr 1fr 1fr;
	gap: 0.5rem;
}
.office-stat-row .office-stat {
	padding: 0.55rem 0.6rem;
	text-align: center;
}
.office-stat-row .office-stat-value {
	font-size: 1rem;
}
.office-legend {
	display: flex;
	gap: 0.75rem;
	font-size: 0.75rem;
	color: var(--text-muted);
}
.office-legend-dot {
	display: inline-block;
	width: 8px;
	height: 8px;
	border-radius: 50%;
	margin-right: 0.35rem;
	vertical-align: middle;
}
.office-actions {
	display: flex;
	justify-content: flex-end;
	gap: 0.5rem;
}

/* SVG hover lift on workstations with prefers-reduced-motion gate */
.office-stage svg .ws-group {
	transition: transform 220ms var(--ease-out);
	transform-box: fill-box;
	transform-origin: center;
}
@media (prefers-reduced-motion: no-preference) {
	.office-stage svg .ws-group:hover {
		transform: translateY(-2px);
	}
}
.office-stage svg .ws-label {
	font-family: var(--font-display, "Inter", sans-serif);
	font-size: 11px;
	font-weight: 500;
	fill: var(--text);
}
.office-stage svg .ws-label.muted {
	fill: var(--text-muted);
}

/* Header brand row tweak (when light) — show a small mascot dot */
body.theme-marvis .workspace-brand::before {
	content: "";
	display: inline-block;
	width: 10px;
	height: 10px;
	border-radius: 50%;
	background: var(--accent);
	margin-right: 0.5rem;
	vertical-align: middle;
	transform: translateY(-1px);
}

