arguments.command:
cat >> packages/web/src/style.css << 'EOF'

/* =================================
   Marvis polish (default light theme)
   ================================= */

/* Brand mark dot in front of "pi Hub" */
.workspace-brand::before {
  content: "";
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
  margin-right: 0.5rem;
  vertical-align: middle;
  transform: translateY(-1px);
}
.workspace-brand,
.workspace-brand-accent {
  background: none;
  -webkit-text-fill-color: currentColor;
  color: var(--text);
  font-weight: 600;
  letter-spacing: -0.02em;
}

/* Top accent bar — single accent color */
.accent-bar {
  background: var(--accent);
  height: 2px;
  opacity: 0.9;
}

/* Capsule secondary buttons */
.secondary-btn {
  border-radius: var(--radius-pill);
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  color: var(--text);
  transition:
    background var(--duration-fast) var(--ease-out),
    transform var(--duration-fast) var(--ease-out),
    box-shadow var(--duration-fast) var(--ease-out);
}
.secondary-btn:hover {
  background: #ececee;
}
body.theme-dark .secondary-btn:hover {
  background: var(--bg-raised);
}

/* Capsule inputs */
input[type="text"],
input:not([type]),
input[type="search"],
input[type="email"] {
  border-radius: var(--radius-pill);
  border: 1px solid var(--border);
  background: var(--bg-subtle);
  color: var(--text);
  padding: 0.55rem 0.9rem;
}
input:focus,
textarea:focus {
  outline: none;
  border-color: var(--accent-ring);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

/* Chat bubbles — Marvis pill / soft card */
.msg.user .msg-body,
.msg.user-msg .msg-body,
.msg.user .bubble,
.msg-user .bubble {
  background: var(--user-bg);
  border: 1px solid var(--user-border);
  border-radius: 18px 18px 4px 18px;
  color: var(--text);
}
.msg.assistant .msg-body,
.msg.assistant .msg-collapse-conclusion,
.msg-assistant .bubble {
  background: var(--assistant-bg);
  border: 1px solid var(--border);
  border-radius: 4px 18px 18px 18px;
  box-shadow: var(--shadow-sm);
  color: var(--text-body);
}

/* Empty / dot-only assistant reply notice */
.msg.assistant.msg-empty .msg-collapse-conclusion {
  font-style: italic;
  color: var(--text-muted);
  background: var(--warning-bg);
  border-color: rgba(217, 138, 4, 0.2);
}
.msg-empty-icon {
  display: inline-block;
  margin-right: 0.4rem;
  color: var(--warning-text);
  font-style: normal;
}

/* Modals — soft, animated */
.modal-backdrop {
  background: rgba(15, 15, 16, 0.32);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
body.theme-dark .modal-backdrop {
  background: rgba(0, 0, 0, 0.6);
}
.modal {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  color: var(--text);
}
@media (prefers-reduced-motion: no-preference) {
  .modal {
    animation: marvis-modal-in 220ms var(--ease-out);
  }
  .modal-backdrop {
    animation: marvis-fade-in 180ms var(--ease-out);
  }
}
@keyframes marvis-modal-in {
  from { opacity: 0; transform: translateY(8px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes marvis-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* Sidebar account row at bottom of room rail */
.room-rail-account {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.75rem 1rem;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
  background: var(--bg-surface);
}
.room-rail-account-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--text);
  color: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 600;
  flex-shrink: 0;
}
.room-rail-account-name {
  flex: 1;
  font-size: 0.85rem;
  color: var(--text);
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.room-rail-account-signout {
  font-size: 0.7rem;
  color: var(--text-muted);
  background: none;
  border: none;
  padding: 0.2rem 0.4rem;
  cursor: pointer;
  border-radius: var(--radius-sm);
}
.room-rail-account-signout:hover {
  background: var(--bg-subtle);
  color: var(--text);
}

/* Sidebar quick-action group */
.room-rail-actions {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.25rem 0.5rem 0.5rem;
}
.room-rail-action {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.55rem 0.75rem;
  background: none;
  border: none;
  border-radius: var(--radius-md);
  color: var(--text);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  transition: background var(--duration-fast) var(--ease-out);
}
.room-rail-action:hover {
  background: var(--bg-subtle);
}
.room-rail-action-icon {
  display: inline-flex;
  width: 20px;
  height: 20px;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

/* Hero state (empty conversation) */
.chat-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2.5rem 1.5rem;
  flex: 1;
  text-align: center;
  gap: 1.25rem;
  animation: marvis-fade-in var(--duration-normal) var(--ease-out);
}
.chat-hero-mark {
  width: 64px;
  height: 64px;
  border-radius: 18px;
  background: var(--text);
  color: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: -0.04em;
  box-shadow: var(--shadow-md);
  position: relative;
}
.chat-hero-mark::after {
  content: "";
  position: absolute;
  bottom: 8px;
  left: 14px;
  right: 14px;
  height: 4px;
  border-radius: 2px;
  background: var(--accent);
}
.chat-hero-title {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -0.02em;
}
.chat-hero-sub {
  margin: 0;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.chat-hero-cards {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 0.75rem;
  width: min(720px, 100%);
}
.chat-hero-card {
  text-align: left;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 0.9rem 1rem 0.9rem;
  cursor: pointer;
  transition:
    transform var(--duration-fast) var(--ease-out),
    box-shadow var(--duration-fast) var(--ease-out),
    border-color var(--duration-fast) var(--ease-out);
  position: relative;
  font: inherit;
  color: inherit;
}
.chat-hero-card-title {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
  margin: 0 0 0.25rem;
}
.chat-hero-card-body {
  font-size: 0.78rem;
  color: var(--text-muted);
  line-height: 1.4;
  margin: 0;
}
.chat-hero-card-arrow {
  position: absolute;
  right: 0.9rem;
  bottom: 0.7rem;
  font-size: 1rem;
  color: var(--text-muted);
  opacity: 0;
  transform: translateX(-4px);
  transition:
    opacity var(--duration-fast) var(--ease-out),
    transform var(--duration-fast) var(--ease-out);
}
@media (prefers-reduced-motion: no-preference) {
  .chat-hero-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
    border-color: var(--accent-ring);
  }
  .chat-hero-card:hover .chat-hero-card-arrow {
    opacity: 1;
    transform: translateX(0);
  }
}
.chat-hero-tabs {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.5rem;
}
.chat-hero-tab {
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-pill);
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  font-size: 0.78rem;
  cursor: pointer;
  font-weight: 500;
}
.chat-hero-tab.active {
  background: var(--text);
  color: var(--bg-surface);
}

/* Office (Marvis 办公室) modal */
.office-modal {
  width: min(960px, calc(100vw - 2rem));
  max-height: calc(100vh - 4rem);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
}
.office-header {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
}
.office-title {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
}
.office-room {
  font-family: var(--mono);
  font-size: 0.75rem;
  color: var(--text-muted);
}
.office-body {
  display: grid;
  grid-template-columns: 1fr 240px;
  gap: 1rem;
  min-height: 0;
  flex: 1;
}
.office-stage {
  background: var(--bg-subtle);
  border-radius: var(--radius-lg);
  padding: 1rem;
  overflow: auto;
  display: flex;
  align-items: center;
  justify-content: center;
}
.office-stage svg {
  max-width: 100%;
  height: auto;
  display: block;
}
.office-side {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.office-stat {
  background: var(--bg-subtle);
  border-radius: var(--radius-md);
  padding: 0.75rem 0.9rem;
  border: 1px solid var(--border);
}
.office-stat-label {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin: 0 0 0.25rem;
}
.office-stat-value {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text);
  margin: 0;
}
.office-stat-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 0.5rem;
}
.office-stat-row .office-stat {
  padding: 0.55rem 0.6rem;
  text-align: center;
}
.office-stat-row .office-stat-value {
  font-size: 1rem;
}
.office-legend {
  display: flex;
  gap: 0.75rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}
.office-legend-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 0.35rem;
  vertical-align: middle;
}
.office-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
}
.office-stage svg .ws-group {
  transition: transform 220ms var(--ease-out);
}
@media (prefers-reduced-motion: no-preference) {
  .office-stage svg .ws-group:hover {
    transform: translateY(-2px);
  }
}
.office-stage svg .ws-label {
  font-family: var(--font-display, "Inter", sans-serif);
  font-size: 11px;
  font-weight: 500;
  fill: var(--text);
}
.office-stage svg .ws-label.muted {
  fill: var(--text-muted);
}
