	function renderHistory(msgs: unknown[]): void {
		// Prevent visible scroll during rendering by hiding overflow temporarily.
		messages.style.overflow = "hidden";
		messages.innerHTML = "";
		streamingAssistantEl = null;
		streamingAssistantHost = null;
